def find_maximum_nesting_level(paren_string: str) -> int:
    """ A string representing multiple nested parenthes group separated by spaces.
    Return the deepest level of nesting of parentheses for the group.
    E.g. (()()) has maximum two levels of nesting while ((())) has three.
    """
    depth = 0
    max_depth = 0
    for ch in paren_string:
        if ch == '(':
            depth += 1
        if ch == ')':
            max_depth = max(max_depth, depth)
            depth -= 1
    return max_depth


