def find_deepest_level_of_nested_parens(paren_string: str) -> int:
    """ This function returns the deepest level of nested parentheses.
    Example: (()()) has maximum two levels of nesting while ((())) has three.
    """
    deepest_level_of_nested_parens = 0
    stack = []
    for paren_char in paren_string:
        if paren_char == '(':
            stack.append(paren_char)
        elif paren_char == ')':
            stack.pop()
            if len(stack) > deepest_level_of_nested_parens:
                deepest_level_of_nested_parens += 1
    return deepest_level_of_nested_parens


