def get_deepest_nesting_level(group: str) -> int:
    """ Input is a single parenthesized group separated by white-space.
    Return the deepest nesting level of the group.
    E.g. (()()) has maximum two levels of nesting while ((())) has three.
    >>> get_deepest_nesting_level('(((())))')
    4
    >>> get_deepest_nesting_level('()')
    1
    """
    group_counter = {}
    max_deepest = 0
    for char in group:
        if char not in group_counter:
            group_counter[char] = 0
        if char == '(':
            group_counter['('] += 1
        elif char == ')':
            group_counter['('] -= 1
        if group_counter['('] > max_deepest:
            max_deepest = group_counter['(']
    return max_deepest


