def is_balanced(s: str) -> bool:
    """
    This function checks whether the parentheses in the input string are balanced or not.
    """
    stack = []

    for char in s:
        if char == "(":
            stack.append(char)
        elif char == ")":
            if len(stack) == 0:
                return False
            stack.pop()

    return len(stack) == 0


